VALUES ('f3c813f0-6fdb-5dc6-8aca-4a525bfc320a', '28997544-0d87-4b05-9ee2-7c474513c108', 'K-12 by grade band and year, with three hour tiers', 'Four grade bands of 3, 3, 3 and 4 years. Three hour tiers (lower K-4, middle 5-8, upper 9-12) sit beside the bands, so grade 5 is in the 3-5 band and in the middle tier. Hours are placeholders and editable.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"lower","label":"Lower grades (K-4)","where":{"year":{"range":[1,5],"absolute":true}},"duration":{"low":"PT15H","high":"PT45H"},"note":"Placeholder from Dustin 2026-10-25: 15-45 hours a year."},{"key":"middle","label":"Middle grades (5-8)","where":{"year":{"range":[6,9],"absolute":true}},"duration":{"low":"PT40H","high":"PT80H"},"note":"Default 40-80 hours a year, adjustable to local conditions."},{"key":"upper","label":"Upper grades (9-12)","where":{"year":{"range":[10,13],"absolute":true}},"duration":{"low":"PT100H","high":"PT150H"},"note":"Placeholder from Dustin 2026-10-25: 100-150 hours a year."}]}'::jsonb, 'Hours per year: Dustin Eirdosh, 2026-10-25 (lower grades 15-45, upper grades 100-150; middle 40-80 as the default he gave). All placeholders.', 'proposed') ON CONFLICT (id) DO NOTHING;
