INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('d9c5d435-307a-518a-9e1e-21daa6ce131c', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, 'f3c813f0-6fdb-5dc6-8aca-4a525bfc320a', NULL, 'Biology gets 15-45 hours a year in the lower grades (K-4).', 'estimate', 'low', 'Dustin Eirdosh, 2026-10-25.', 'His working estimate. No published source yet.', '{"low":"PT15H","high":"PT45H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('9f004ad0-1369-5b07-bed0-0c88837a7390', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, 'f3c813f0-6fdb-5dc6-8aca-4a525bfc320a', NULL, 'Biology gets 40-80 hours a year in the middle grades (5-8). Adjust to local conditions.', 'placeholder', 'low', 'Dustin Eirdosh, 2026-10-25 (default he gave).', 'No estimate was given for the middle tier before this default. Local conditions differ.', '{"low":"PT40H","high":"PT80H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('99cd52ec-02c7-5342-9c6b-20a538fd38ee', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, 'f3c813f0-6fdb-5dc6-8aca-4a525bfc320a', NULL, 'Biology gets 100-150 hours a year in the upper grades (9-12).', 'estimate', 'low', 'Dustin Eirdosh, 2026-10-25.', 'His working estimate. No published source yet.', '{"low":"PT100H","high":"PT150H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('937c6b0b-cb32-5b44-8234-fccb649d3b3d', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, 'f3c813f0-6fdb-5dc6-8aca-4a525bfc320a', NULL, 'The tiers are K-4, 5-8 and 9-12, and kindergarten counts as year 1, so Grade 5 is year 6 in the 3-5 band and the middle tier.', 'derived', 'medium', 'Dustin Eirdosh, 2026-10-25.', 'Tier edges are a property of the axis. They need not follow the LPM grade bands.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('abcd88c0-ab3f-5347-bd67-512cfd0cdf9c', '28997544-0d87-4b05-9ee2-7c474513c108', '20866981-f8a9-5d3f-a191-b3c011536527', NULL, NULL, 'Evolution''s share of biology teaching time is between 10 and 30 percent.', 'placeholder', 'low', 'No source.', 'The true share is unknown. Every derived number carries the range. Compare curricula in use before trusting any single figure.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('f4db6ed6-1516-55ae-b626-aab755b1c58a', '28997544-0d87-4b05-9ee2-7c474513c108', '20866981-f8a9-5d3f-a191-b3c011536527', NULL, NULL, 'Biology teaching is spread evenly through each year, so the last fifth of the year holds a fifth of the biology time.', 'derived', 'low', 'Design note 2026-10-25, section 5.4.', 'Used to turn a position in the year into hours. A year with uneven biology time would change the hours of a block.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('636692e7-2dcb-57f5-9634-1679551fe8e3', '28997544-0d87-4b05-9ee2-7c474513c108', '20866981-f8a9-5d3f-a191-b3c011536527', NULL, NULL, 'Within a grade band, every stage takes an equal part of the band''s evolution time.', 'derived', 'low', 'Design note 2026-10-25, section 5.5.', 'A starting rule. Stages differ in size, so equal parts are an approximation. Override per stage when better information exists.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('eabff656-392d-52bb-84c5-f559fa0c56aa', '28997544-0d87-4b05-9ee2-7c474513c108', '20866981-f8a9-5d3f-a191-b3c011536527', NULL, NULL, 'The same share of biology time applies in every year of the K-12 span.', 'placeholder', 'low', 'No source.', 'Different tiers may justify different shares.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('2abab8e9-f5e5-53e6-88cf-f6b77e83c9dd', '28997544-0d87-4b05-9ee2-7c474513c108', '20866981-f8a9-5d3f-a191-b3c011536527', NULL, NULL, 'A topic gives 15 percent of its time to its reinforcing concepts as threaded time. Its primary concepts share the rest equally.', 'placeholder', 'low', 'No source.', 'Concept time is derived from topic time. The split is an accounting rule and makes no claim about learning.', '{"reinforcing_share":0.15}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b6b5b2f3-3888-5b89-a397-7ceb5f3489d7', '28997544-0d87-4b05-9ee2-7c474513c108', '83f3afbb-bc49-5bae-b11b-26994019383d', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the evolution time as a thread.', 'placeholder', 'low', 'No source.', 'The CETM model suggests a short block to build an idea and then threading, with a rule for the proportion. That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('1e0fd31e-6b3f-587e-8de4-beced3784287', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, '5784d0f4-8893-510b-a8e4-b39424f018d5', NULL, 'The example school year runs from 2026-08-31 to 2027-06-25, with three breaks and five 45-minute biology sessions a week.', 'calendar-constraint', 'low', 'Placeholder. Not an official calendar.', 'Replace with the dates, timetable and breaks of a named school system, each with its source.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('d880d157-9dd5-5459-8200-ab99533ada8a', '28997544-0d87-4b05-9ee2-7c474513c108', NULL, NULL, 'e6ef73a4-6b1a-5e9b-833c-ea4e1ebf5846', 'Generic positions map to the same fraction of the target year''s teaching minutes, so holidays drop out of the sequence.', 'derived', 'medium', 'Design note 2026-10-25, section 5.9.', 'The alternative rule, date offset, keeps holidays in the sequence and loses the teaching time that falls inside them.', NULL) ON CONFLICT (id) DO NOTHING;

