INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, source, status)
VALUES ('61b50773-f946-5657-a957-1faf4e02f3b7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'K-12 by grade band and year, with three hour tiers', 'Four grade bands of 3, 3, 3 and 4 years. Three hour tiers (lower K-4, middle 5-8, upper 9-12) sit beside the bands, so grade 5 is in the 3-5 band and in the middle tier. Hours are placeholders and editable.', 'generated', '{"kind":"generated","levels":[{"key":"band","label":"Grade band","per_parent":4,"names":["K-2","3-5","6-8","9-12"]},{"key":"year","label":"Year","per_parent":[3,3,3,4],"names":["Grade K","Grade 1","Grade 2","Grade 3","Grade 4","Grade 5","Grade 6","Grade 7","Grade 8","Grade 9","Grade 10","Grade 11","Grade 12"]}],"segments":[{"key":"lower","label":"Lower grades (K-4)","where":{"year":{"range":[1,5],"absolute":true}},"duration":{"low":"PT15H","high":"PT45H"},"note":"Placeholder from Dustin 2026-10-25: 15-45 hours a year."},{"key":"middle","label":"Middle grades (5-8)","where":{"year":{"range":[6,9],"absolute":true}},"duration":{"low":"PT40H","high":"PT80H"},"note":"Default 40-80 hours a year, adjustable to local conditions."},{"key":"upper","label":"Upper grades (9-12)","where":{"year":{"range":[10,13],"absolute":true}},"duration":{"low":"PT100H","high":"PT150H"},"note":"Placeholder from Dustin 2026-10-25: 100-150 hours a year."}]}'::jsonb, 'Hours per year: Dustin Eirdosh, 2026-10-25 (lower grades 15-45, upper grades 100-150; middle 40-80 as the default he gave). All placeholders.', 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, source, status)
VALUES ('43cc4e4f-146a-54a3-9dd5-bb9e705207ba', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'Generic 365-day school year, K-12 (13 years)', 'A year of 365 days with no weekdays, holidays or start month, repeated for 13 years. Plans written here can be projected onto any dated calendar.', 'generic-year', '{"kind":"generic-year","year_length":365,"levels":[{"key":"year","label":"Year","per_parent":13},{"key":"day","label":"Day","per_parent":365}]}'::jsonb, 'Design note 2026-10-25, section 5.9.', 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_axes (id, project_id, name, description, kind, definition, source, status)
VALUES ('dcd89c0b-9e65-587e-80b8-fc0eadf9005c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'Example school year 2026/27 (placeholder dates)', 'An example dated calendar for showing the fit report. The dates, the weekly timetable and the breaks are placeholders and match no jurisdiction. Replace them with a real calendar and its source.', 'dated', '{"kind":"dated","levels":[],"dated":{"start":"2026-08-31","end":"2027-06-25","sessions":[{"weekday":1,"minutes":45,"label":"Biology"},{"weekday":2,"minutes":45,"label":"Biology"},{"weekday":3,"minutes":45,"label":"Biology"},{"weekday":4,"minutes":45,"label":"Biology"},{"weekday":5,"minutes":45,"label":"Biology"}],"non_teaching":[{"from":"2026-10-12","to":"2026-10-23","label":"Autumn break (placeholder)"},{"from":"2026-12-21","to":"2027-01-03","label":"Winter break (placeholder)"},{"from":"2027-03-29","to":"2027-04-09","label":"Spring break (placeholder)"}]}}'::jsonb, 'Placeholder. Not an official calendar.', 'proposed') ON CONFLICT (id) DO NOTHING;
