VALUES ('ba65f3c2-a952-56e2-8883-7844e9a30f74', '371fce26-d1f3-439b-95df-0a0e38b8a824', '61b50773-f946-5657-a957-1faf4e02f3b7', 'Starter plan: one unit at the end of each year', 'Evolution is taught as one unit in the last part of each school year. Placeholder numbers. It shows a shape and makes no recommendation.', 'planned', '{"preset":"capstone","share":{"low":0.1,"high":0.3},"returns_per_year":2,"thread_fraction":0.25,"reinforcing_share":0.15}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
