VALUES ('69bb9a90-fbf5-5b32-a9e1-86f2fc0a6e9e', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '61b50773-f946-5657-a957-1faf4e02f3b7', NULL, 'Biology gets 15-45 hours a year in the lower grades (K-4).', 'estimate', 'low', 'Dustin Eirdosh, 2026-10-25.', 'His working estimate. No published source yet.', '{"low":"PT15H","high":"PT45H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('273d765a-83b6-5224-aa25-b80f5bae9e63', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '61b50773-f946-5657-a957-1faf4e02f3b7', NULL, 'Biology gets 40-80 hours a year in the middle grades (5-8). Adjust to local conditions.', 'placeholder', 'low', 'Dustin Eirdosh, 2026-10-25 (default he gave).', 'No estimate was given for the middle tier before this default. Local conditions differ.', '{"low":"PT40H","high":"PT80H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('40a51ea3-ff27-54b4-83d0-def89161a444', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '61b50773-f946-5657-a957-1faf4e02f3b7', NULL, 'Biology gets 100-150 hours a year in the upper grades (9-12).', 'estimate', 'low', 'Dustin Eirdosh, 2026-10-25.', 'His working estimate. No published source yet.', '{"low":"PT100H","high":"PT150H"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('82de0a58-3591-54b2-860d-45e313626348', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, '61b50773-f946-5657-a957-1faf4e02f3b7', NULL, 'The tiers are K-4, 5-8 and 9-12, and kindergarten counts as year 1, so Grade 5 is year 6 in the 3-5 band and the middle tier.', 'derived', 'medium', 'Dustin Eirdosh, 2026-10-25.', 'Tier edges are a property of the axis. They need not follow the LPM grade bands.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('3a662fa8-4fc2-5e52-9896-f31909959432', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba65f3c2-a952-56e2-8883-7844e9a30f74', NULL, NULL, 'Evolution''s share of biology teaching time is between 10 and 30 percent.', 'placeholder', 'low', 'No source.', 'The true share is unknown. Every derived number carries the range. Compare curricula in use before trusting any single figure.', '{"low":0.1,"high":0.3}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('a81f009f-75be-52d5-b966-b3ff2588589e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba65f3c2-a952-56e2-8883-7844e9a30f74', NULL, NULL, 'Biology teaching is spread evenly through each year, so the last fifth of the year holds a fifth of the biology time.', 'derived', 'low', 'Design note 2026-10-25, section 5.4.', 'Used to turn a position in the year into hours. A year with uneven biology time would change the hours of a block.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('b72779a0-f686-56bb-9be3-9f6acfec6e3f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba65f3c2-a952-56e2-8883-7844e9a30f74', NULL, NULL, 'Within a grade band, every stage takes an equal part of the band''s evolution time.', 'derived', 'low', 'Design note 2026-10-25, section 5.5.', 'A starting rule. Stages differ in size, so equal parts are an approximation. Override per stage when better information exists.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('d24e8d24-0d41-541f-8e08-8f7a7ab20347', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba65f3c2-a952-56e2-8883-7844e9a30f74', NULL, NULL, 'The same share of biology time applies in every year of the K-12 span.', 'placeholder', 'low', 'No source.', 'Different tiers may justify different shares.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('a9d7a740-b7f6-5e7e-a071-f8ffab37f70a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ba65f3c2-a952-56e2-8883-7844e9a30f74', NULL, NULL, 'A topic gives 15 percent of its time to its reinforcing concepts as threaded time. Its primary concepts share the rest equally.', 'placeholder', 'low', 'No source.', 'Concept time is derived from topic time. The split is an accounting rule and makes no claim about learning.', '{"reinforcing_share":0.15}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('ebb7f3b6-e9c7-505e-9497-432e79148343', '371fce26-d1f3-439b-95df-0a0e38b8a824', '3e59fbdd-06a8-5a87-9322-29d94fc6a01c', NULL, NULL, 'The spiral plan has two blocks per year and keeps a quarter of the evolution time as a thread.', 'placeholder', 'low', 'No source.', 'The CETM model suggests a short block to build an idea and then threading, with a rule for the proportion. That proportion is a hypothesis to test.', '{"returns_per_year":2,"thread_fraction":0.25}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('84a22512-eb0a-5c10-98f6-9c000e77d5f3', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, 'dcd89c0b-9e65-587e-80b8-fc0eadf9005c', NULL, 'The example school year runs from 2026-08-31 to 2027-06-25, with three breaks and five 45-minute biology sessions a week.', 'calendar-constraint', 'low', 'Placeholder. Not an official calendar.', 'Replace with the dates, timetable and breaks of a named school system, each with its source.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('929e31e1-245c-5081-8ece-14d4dba89b3d', '371fce26-d1f3-439b-95df-0a0e38b8a824', NULL, NULL, 'fdfb54c3-d344-5ea8-91bc-8d20d8d3e3c3', 'Generic positions map to the same fraction of the target year''s teaching minutes, so holidays drop out of the sequence.', 'derived', 'medium', 'Design note 2026-10-25, section 5.9.', 'The alternative rule, date offset, keeps holidays in the sequence and loses the teaching time that falls inside them.', NULL) ON CONFLICT (id) DO NOTHING;

